<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install MODRIK</title>
<style>body{font-family:system-ui;background:#f8fafc;color:#0f172a;margin:0}.wrap{max-width:760px;margin:3rem auto;padding:1rem}.card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:1.5rem;box-shadow:0 8px 25px #0f172a12}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}label{display:block;font-weight:600;font-size:.9rem}input{width:100%;box-sizing:border-box;padding:.7rem;border:1px solid #cbd5e1;border-radius:8px;margin-top:.3rem}button{background:#25546f;color:#fff;border:0;border-radius:9px;padding:.8rem 1.2rem;font-weight:700}.secondary{background:#e2e8f0;color:#0f172a}.actions{display:flex;justify-content:space-between;gap:1rem;margin-top:1.5rem}.ok{color:#15803d}.bad,.errors{color:#b91c1c}.steps{color:#475569;font-size:.9rem;margin-bottom:1rem}.panel[hidden]{display:none}.review{line-height:1.7}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head>
